/**
 * Prepares the released TissUUmaps docs and apps for the website build
 *
 * The TissUUmaps release workflow writes every released MAJOR.MINOR line to
 * `releases/<line>/`: `release.json` with the released `version`, and `docs/`
 * with the docs and the API docs generated by typedoc. The lines selected by
 * {@link selectVersionsToDeploy} become Docusaurus versions through
 * `docusaurus docs:version` (`versioned_docs/`, `versioned_sidebars/` and
 * `versions.json`), and their apps, downloaded from
 * the TissUUmaps releases, are served under `app/<line>/`, with `app/`
 * redirecting to the latest line. The outputs are generated (gitignored) and
 * replaced on every run.
 *
 * Run from the site directory (`node scripts/prepare.ts`); downloading the
 * apps needs a `gh` token, `--skip-apps` skips them (e.g. for checks). Inserts
 * `.github/pages/custom.html` into every app page (the release assets stay
 * free of it). The functions are exported for the tests, which import this
 * module without running it.
 */
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import semver from "semver";

/** The repository whose releases carry the apps */
const appRepository = "TissUUmaps/TissUUmaps";

/**
 * The marker in the app page (`apps/tissuumaps/index.html` in TissUUmaps) that
 * the custom HTML replaces; an app page without it fails the preparation,
 * since the custom HTML would otherwise silently be missing
 */
const customHTMLMarker = "<!-- GHA_CUSTOM_HTML -->";

/**
 * The MAJOR.MINOR line of a version, which names its docs version and app directory
 *
 * @param version - The version
 * @returns The line, e.g. `4.1` for `4.1.2` and for `4.1.0-rc.1`
 */
export function formatLine(version: string): string {
  return `${semver.major(version)}.${semver.minor(version)}`;
}

/**
 * Selects the versions to deploy from the released versions
 *
 * Every stable version is deployed. A prerelease is only deployed if it ranks
 * above the highest stable version, so abandoned prerelease lines do not
 * accumulate.
 *
 * @param versions - The released versions, one per MAJOR.MINOR line (the
 * TissUUmaps release workflow never replaces a line's stable version with a
 * prerelease), in any order
 * @returns `versionsToDeploy`, in ascending order, and `latestVersion`, the
 * version shown by default: the highest stable version, or the highest
 * prerelease while there is none (`null` without any version to deploy)
 */
export function selectVersionsToDeploy(versions: string[]): {
  versionsToDeploy: string[];
  latestVersion: string | null;
} {
  const sortedVersions = versions.toSorted(semver.compare);
  const highestStableVersion = sortedVersions.findLast(
    (version) => semver.prerelease(version) === null,
  );
  const versionsToDeploy = sortedVersions.filter(
    (version) =>
      semver.prerelease(version) === null ||
      highestStableVersion === undefined ||
      semver.gt(version, highestStableVersion),
  );
  const latestVersion = highestStableVersion ?? versionsToDeploy.at(-1) ?? null;
  return { versionsToDeploy, latestVersion };
}

/**
 * Reads the released versions from the releases directory
 *
 * @param releasesDir - The releases directory, with one directory per line
 * (other entries are ignored)
 * @returns The released version of every line; empty without releases
 */
export function readReleases(releasesDir: string): string[] {
  if (!existsSync(releasesDir)) {
    return [];
  }
  const lines = readdirSync(releasesDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name);
  return lines.map((line) => {
    const release = JSON.parse(
      readFileSync(join(releasesDir, line, "release.json"), "utf8"),
    ) as { version: string };
    const { version } = release;
    if (semver.valid(version) !== version) {
      throw new Error(`${version} is not a semantic version`);
    }
    if (formatLine(version) !== line) {
      throw new Error(`${releasesDir}/${line} holds ${version}`);
    }
    return version;
  });
}

/**
 * Prepares the apps of the given versions under `static/app/` in the site
 * directory, replacing any previously prepared ones
 *
 * @param options.siteDir - The site directory
 * @param options.versions - The versions to prepare
 * @param options.latestVersion - The version `app/` redirects to
 * @param options.customHtml - The HTML to insert into every app page
 * @param options.assetsDir - A directory holding the app assets
 * (`tissuumaps-<version>.zip`); downloaded from the releases if omitted
 */
export function prepareApps(options: {
  siteDir: string;
  versions: string[];
  latestVersion: string;
  customHtml: string;
  assetsDir?: string;
}): void {
  const { siteDir, versions, latestVersion, customHtml, assetsDir } = options;
  const appDir = join(siteDir, "static", "app");
  rmSync(appDir, { recursive: true, force: true });
  mkdirSync(appDir, { recursive: true });
  const zipDir = assetsDir ?? mkdtempSync(join(tmpdir(), "tissuumaps-app-"));
  try {
    for (const version of versions) {
      const asset = `tissuumaps-${version}.zip`;
      if (!assetsDir) {
        // prettier-ignore
        execFileSync("gh", [
          "release", "download", `tissuumaps@${version}`,
          "--repo", appRepository,
          "--dir", zipDir,
          "--pattern", asset,
        ]);
      }
      const lineDir = join(appDir, formatLine(version));
      // prettier-ignore
      execFileSync("unzip", [
        "-q", join(zipDir, asset),
        "-d", lineDir,
      ]);
      const page = join(lineDir, "index.html");
      const html = readFileSync(page, "utf8");
      if (!html.includes(customHTMLMarker)) {
        throw new Error(`${page} has no ${customHTMLMarker} marker`);
      }
      writeFileSync(
        page,
        html.replace(customHTMLMarker, () => customHtml),
      );
    }
  } finally {
    if (!assetsDir) {
      rmSync(zipDir, { recursive: true, force: true });
    }
  }
  const latestLine = formatLine(latestVersion);
  writeFileSync(
    join(appDir, "index.html"),
    `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="robots" content="noindex" />
    <meta http-equiv="refresh" content="0; url=${latestLine}/" />
    <title>TissUUmaps</title>
  </head>
  <body>
    <p><a href="${latestLine}/">Latest release</a></p>
  </body>
</html>
`,
  );
}

/**
 * Prepares the docs of the given versions as Docusaurus versions in the site
 * directory, replacing any previously prepared ones
 *
 * Every version is created by `pnpm exec docusaurus docs:version`, with its
 * released docs as the current version (`TISSUUMAPS_DOCS`, see
 * `docusaurus.config.ts`).
 *
 * @param siteDir - The site directory
 * @param releasesDir - The releases directory
 * @param versions - The versions to prepare
 */
export function prepareDocs(
  siteDir: string,
  releasesDir: string,
  versions: string[],
): void {
  // docs:version refuses to overwrite existing versions
  for (const output of [
    "versioned_docs",
    "versioned_sidebars",
    "versions.json",
  ]) {
    rmSync(join(siteDir, output), { recursive: true, force: true });
  }
  // docs:version prepends to versions.json, which lists the highest version first
  for (const line of versions.map(formatLine)) {
    execFileSync("pnpm", ["exec", "docusaurus", "docs:version", line], {
      cwd: siteDir,
      env: {
        ...process.env,
        TISSUUMAPS_DOCS: join(releasesDir, line, "docs"),
      },
      stdio: "inherit",
    });
  }
}

/**
 * Prepares the released docs and apps (see above)
 *
 * @param options.siteDir - The site directory
 * @param options.skipApps - Whether to skip the apps
 * @param options.assetsDir - See {@link prepareApps}
 */
export function prepare(options: {
  siteDir: string;
  skipApps: boolean;
  assetsDir?: string;
}): void {
  const { siteDir, skipApps, assetsDir } = options;
  const releasesDir = join(siteDir, "releases");
  const { versionsToDeploy, latestVersion } = selectVersionsToDeploy(
    readReleases(releasesDir),
  );
  if (!latestVersion) {
    throw new Error(`${releasesDir} holds no releases; nothing to prepare`);
  }
  if (skipApps) {
    rmSync(join(siteDir, "static", "app"), { recursive: true, force: true });
  } else {
    prepareApps({
      siteDir,
      versions: versionsToDeploy,
      latestVersion,
      customHtml: readFileSync(
        join(siteDir, ".github", "pages", "custom.html"),
        "utf8",
      ),
      assetsDir,
    });
  }
  prepareDocs(siteDir, releasesDir, versionsToDeploy);
  for (const version of versionsToDeploy) {
    console.log(`prepared ${version} as ${formatLine(version)}`);
  }
  console.log(`latest: ${formatLine(latestVersion)}`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  prepare({
    siteDir: process.cwd(),
    skipApps: process.argv.includes("--skip-apps"),
  });
}
